package com.mutqin.app

data class TajweedLesson(
  val id: Int, val title: String, val objective: String, val definition: String,
  val rule: String, val examples: List<String>, val practice: String,
  val commonMistake: String, val references: String
)

val tajweedLessons = listOf(
  TajweedLesson(1,"مدخل إلى علم التجويد","أن يعرف المتعلم معنى التجويد وهدفه.","التجويد لغةً التحسين، واصطلاحًا إعطاء الحروف حقها ومستحقها عند تلاوة القرآن.","يتعلم القارئ إخراج كل حرف من مخرجه، وإعطاءه صفاته، ومراعاة أحكام التلاوة بالمشافهة والتلقي.",listOf("التمييز بين س وص","التمييز بين ت و ط"),"اقرأ الفاتحة على معلّم، واطلب منه تحديد حرف واحد يحتاج إلى تحسين.","اعتبار معرفة أسماء الأحكام وحدها إتقانًا للتلاوة؛ فالأداء يحتاج تدريبًا وسماعًا.","المقدمة الجزرية، باب التجويد."),
  TajweedLesson(2,"الاستعاذة قبل القراءة","أن يميّز المتعلم صيغة الاستعاذة وموضعها.","الاستعاذة هي الالتجاء إلى الله من الشيطان الرجيم، وصيغتها المشهورة: أعوذ بالله من الشيطان الرجيم.","يشرع للقارئ أن يأتي بالاستعاذة عند ابتداء القراءة، ويجهر بها أو يسر بحسب الحال ومقام القراءة.",listOf("أعوذ بالله من الشيطان الرجيم"),"تدرّب على نطق الاستعاذة بوضوح دون استعجال، ثم ابدأ سورة قصيرة.","وصل الاستعاذة بكلام القارئ أو إسقاطها من غير معرفة موضعها وأحكام الابتداء.","سورة النحل: 98؛ كتب القراءات والتجويد في باب الاستعاذة."),
  TajweedLesson(3,"البسملة وأول السورة","أن يعرف المتعلم موضع البسملة عند ابتداء السور.","البسملة هي قول: بسم الله الرحمن الرحيم.","يبدأ القارئ أوائل السور بالبسملة، ما عدا سورة التوبة؛ ولها أوجه معروفة عند وصل آخر السورة بأول التالية، تدرس بالمشافهة.",listOf("بسم الله الرحمن الرحيم"),"اقرأ أول سورة الإخلاص بالبسملة، ثم تعرّف مع معلّمك على أوجه الانتقال بين سورتين.","إثبات البسملة في أول سورة التوبة أو تطبيق أوجه الوصل دون تعلمها.","كتب التجويد والقراءات، باب البسملة بين السورتين."),
  TajweedLesson(4,"مراتب القراءة","أن يفرق المتعلم بين التحقيق والحدر والتدوير.","مراتب الأداء المشهورة: التحقيق، والحدر، والتدوير؛ وهي تتعلق بسرعة القراءة مع مراعاة أحكام التجويد.","لا تخرج أي مرتبة عن صحة الحروف والحركات والمدود والغنن؛ فالسرعة لا تبرر الإخلال.",listOf("التحقيق: قراءة متأنية","الحدر: أسرع مع ضبط الأحكام","التدوير: توسط بينهما"),"اقرأ مقطعًا قصيرًا ببطء مضبوط، ثم بسرعة معتدلة دون إسقاط حرف أو حركة.","الخلط بين الحدر والإسراع المخلّ الذي يذهب الحروف أو الأحكام.","المقدمة الجزرية وشروحها، أبواب مراتب القراءة."),
  TajweedLesson(5,"مخارج الحروف: نظرة عامة","أن يعرف المتعلم المخارج العامة الخمسة.","المخرج هو الموضع الذي ينشأ منه صوت الحرف ويتميز به عن غيره.","المخارج العامة خمسة: الجوف، والحلق، واللسان، والشفتان، والخيشوم؛ وتفصيل المخارج يؤخذ بالتلقي.",listOf("الجوف لحروف المد","الحلق لحروفه","اللسان لأكثر الحروف","الشفتان لبعضها","الخيشوم للغنة"),"انطق أمثلة متنوعة، وحاول ملاحظة موضع خروج الصوت مع معلّم أو تسجيل تعليمي موثوق.","الاعتماد على شكل الحرف المكتوب بدل ملاحظة موضع النطق.","المقدمة الجزرية، باب مخارج الحروف."),
  TajweedLesson(6,"مخرج الجوف وحروف المد","أن يحدد المتعلم حروف المد ومخرجها العام.","الجوف هو الخلاء الممتد داخل الفم والحلق، ومنه تخرج حروف المد الثلاثة.","حروف المد: الألف الساكنة المفتوح ما قبلها، والواو الساكنة المضموم ما قبلها، والياء الساكنة المكسور ما قبلها.",listOf("قَالَ","يَقُولُ","قِيلَ"),"ميّز حرف المد في الأمثلة، واقرأها بمد طبيعي من غير تكلف.","تحويل حرف المد إلى حركة قصيرة أو المبالغة في إطالته دون سبب.","المقدمة الجزرية، باب مخارج الحروف والمدود."),
  TajweedLesson(7,"مخرج الحلق وحروفه","أن يرتب المتعلم حروف الحلق الستة.","للحلق ثلاثة مواضع إجمالية: أقصاه ووسطه وأدناه.","حروف الحلق ستة: الهمزة والهاء من أقصاه، والعين والحاء من وسطه، والغين والخاء من أدناه.",listOf("أَنعَمتَ","هُدًى","عَلِيم","حَكِيم","غَفُور","خَبِير"),"اقرأ الحروف الستة منفردة ثم في كلماتها، مع ملاحظة موضع الصوت دون ضغط الحلق.","تقريب الحاء إلى الهاء أو العين إلى الهمزة؛ صحح ذلك بالسماع من معلّم.","المقدمة الجزرية، باب مخارج الحروف."),
  TajweedLesson(8,"مخرج الشفتين","أن يميّز المتعلم حروف الشفتين.","للشفتين مخرجان تفصيليان مشهوران: بطن الشفة السفلى مع أطراف الثنايا العليا للفاء، وما بين الشفتين للواو غير المدية والباء والميم.","الفاء تخرج من باطن الشفة السفلى مع أطراف الثنايا العليا، والباء والميم والواو غير المدية من بين الشفتين.",listOf("فَتْح","بِسْم","مَال","وَعَد"),"قارن نطق فاء وباء وميم وواو في كلمات واضحة، دون مبالغة في ضم الشفتين.","إخراج الفاء من بين الشفتين أو إخفاء إطباق الشفتين في الباء والميم.","المقدمة الجزرية، باب مخارج الحروف."),
  TajweedLesson(9,"النون الساكنة والتنوين: التعريف","أن يتعرف المتعلم النون الساكنة والتنوين ومواضعهما.","النون الساكنة نون خالية من الحركة، ثابتة لفظًا وخطًا؛ والتنوين نون ساكنة زائدة تلحق آخر الاسم لفظًا لا خطًا.","لهما أربعة أحكام عند وقوعهما قبل الحروف: الإظهار، والإدغام، والإقلاب، والإخفاء.",listOf("مِنْ هَادٍ","عَلِيمٌ حَكِيمٌ","مِنْ بَعْدِ"),"استخرج النون الساكنة أو التنوين من أمثلة قرآنية، ثم حدد الحرف الذي يليهما.","الخلط بين النون الأصلية والتنوين أو الحكم على الكلمة دون النظر إلى الحرف التالي.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين."),
  TajweedLesson(10,"الإظهار الحلقي","أن يحدد المتعلم حروف الإظهار ويطبق النطق الواضح.","الإظهار الحلقي هو إخراج النون الساكنة أو التنوين واضحين من غير إدغام ولا إخفاء عند حروف الحلق.","حروفه ستة: الهمزة والهاء والعين والحاء والغين والخاء؛ فإذا جاء أحدها بعد النون الساكنة أو التنوين أُظهرت النون أو التنوين.",listOf("مِنْ أَهْلِ","مِنْ هَادٍ","أَنْعَمْتَ","عَلِيمٌ حَكِيمٌ","مِنْ غِلٍّ","مِنْ خَيْرٍ"),"اقرأ الأمثلة وحدد حرف الإظهار، ثم سجّل قراءتك واستمع إليها أو اعرضها على معلّم.","إدخال صوت النون في الحرف التالي أو المبالغة في فصل الصوتين بما يخل بسلاسة القراءة.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين؛ شروحها المعتمدة.")

  ,TajweedLesson(11,"الإدغام بغنة","أن يتعرف المتعلم حروف الإدغام المصحوب بالغنة.","الإدغام إدخال النون الساكنة أو التنوين في الحرف الذي يليهما حتى يصيرا كحرف واحد مشدد.","حروف الإدغام بغنة أربعة مجموعة في كلمة ينمو: الياء والنون والميم والواو، ويكون غالبًا من كلمتين.",listOf("مَنْ يَعْمَلْ","مِنْ وَالٍ","مِنْ مَالٍ","مِنْ نِعْمَةٍ"),"حدد النون أو التنوين ثم الحرف التالي، واقرأ المثال مع غنة معتدلة من غير مبالغة.","إظهار النون مستقلة أو حذف الغنة تمامًا أو إطالتها تكلفًا.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين؛ شروحها."),
  TajweedLesson(12,"الإدغام بغير غنة","أن يطبق المتعلم الإدغام عند اللام والراء.","هو إدخال النون الساكنة أو التنوين في اللام أو الراء دون إبقاء غنة النون.","حرفاه اللام والراء، ويكون الإدغام عند التقاء النون الساكنة أو التنوين بأحدهما في كلمتين.",listOf("مِنْ رَبِّهِمْ","مِنْ لَدُنْهُ","هُدًى لِلْمُتَّقِينَ"),"اقرأ الأمثلة مع إدغام النون في اللام أو الراء دون غنة زائدة.","إظهار النون قبل اللام أو الراء، أو إضافة غنة ليست من هذا الحكم.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين."),
  TajweedLesson(13,"الإظهار المطلق","أن يعرف المتعلم مواضع الإظهار المطلق المشهورة.","الإظهار المطلق هو إظهار النون الساكنة إذا جاء بعدها ياء أو واو في الكلمة نفسها، منعًا للإدغام.","ورد في كلمات معدودة مشهورة: الدنيا، بنيان، صنوان، قنوان؛ فلا تدغم النون في الياء أو الواو هنا لاتحاد الكلمة.",listOf("الدُّنْيَا؛ بُنْيَان؛ صِنْوَان؛ قِنْوَان."),"تأمل موضع النون في الكلمات الأربع، وانطقها ظاهرة ثم قارنها بإدغام كلمتين.","تطبيق الإدغام لمجرد مجيء ياء أو واو بعد النون دون مراعاة كونها في كلمة واحدة.","كتب التجويد، باب الإظهار المطلق في أحكام النون الساكنة."),
  TajweedLesson(14,"الإقلاب","أن يتعرف المتعلم حرف الإقلاب وطريقة أدائه.","الإقلاب هو قلب النون الساكنة أو التنوين ميمًا مخفاة عند الباء مع الغنة.","حرفه الباء فقط؛ وتكون الميم مخفاة مع مراعاة الغنة وعدم إطباق الشفتين إطباقًا شديدًا يعوق الخفاء.",listOf("مِنْ بَعْدِ؛ سَمِيعٌ بَصِيرٌ؛ أَنْبِئْهُمْ."),"استخرج الباء بعد النون أو التنوين، ثم تدرب على صوت الميم المخفاة بإشراف معلّم.","إظهار النون بدل قلبها ميمًا، أو تحويل الميم إلى باء، أو المبالغة في الإخفاء.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين."),
  TajweedLesson(15,"الإخفاء الحقيقي","أن يحفظ المتعلم حروف الإخفاء ويعرف فكرته.","الإخفاء الحقيقي حالة بين الإظهار والإدغام، مع بقاء الغنة.","حروفه خمسة عشر: ص ذ ث ك ج ش ق س د ط ز ف ت ض ظ؛ ويكون عند وقوع أحدها بعد النون الساكنة أو التنوين.",listOf("مِنْ صَلْصَالٍ؛ أَنْفُسَكُمْ؛ مِنْ تَحْتِهَا؛ قَوْمًا ظَالِمِينَ."),"اقرأ أمثلة متنوعة، وحدد حرف الإخفاء، وانتبه إلى قرب اللسان من مخرج الحرف التالي دون نطق نون كاملة.","تحويل الإخفاء إلى إظهار واضح أو إدغام كامل، أو جعل الغنة طويلة على نحو متكلف.","تحفة الأطفال وشروحها، باب الإخفاء."),
  TajweedLesson(16,"الميم الساكنة وأحكامها","أن يميز المتعلم أحكام الميم الساكنة الثلاثة.","الميم الساكنة هي الميم الخالية من الحركة، ولها أحكام بحسب الحرف الذي يأتي بعدها.","أحكامها: الإخفاء الشفوي عند الباء، والإدغام الشفوي عند الميم، والإظهار الشفوي عند بقية الحروف.",listOf("تَرْمِيهِمْ بِحِجَارَةٍ؛ لَهُمْ مَا؛ أَنْعَمْتَ عَلَيْهِمْ."),"ضع خطًا تحت الميم الساكنة، ثم صنف الحرف التالي إلى باء أو ميم أو غيرهما.","الخلط بين أحكام الميم الساكنة وأحكام النون الساكنة والتنوين.","تحفة الأطفال، باب أحكام الميم والنون المشددتين والميم الساكنة."),
  TajweedLesson(17,"الإخفاء الشفوي","أن يؤدي المتعلم الميم الساكنة قبل الباء.","الإخفاء الشفوي هو إخفاء الميم الساكنة عند الباء مع بقاء الغنة.","حرفه الباء، ويكون بإخفاء الميم عندها مع غنة، ويؤخذ ضبطه بالمشافهة.",listOf("تَرْمِيهِمْ بِحِجَارَةٍ؛ وَمَا هُمْ بِمُؤْمِنِينَ."),"كرر المثال ببطء، ولاحظ بقاء الغنة مع عدم فصل الميم عن الباء فصلًا ظاهرًا.","إظهار الميم إظهارًا كاملًا أو إدغامها في الباء.","تحفة الأطفال، باب أحكام الميم الساكنة."),
  TajweedLesson(18,"الإدغام الشفوي","أن يطبق المتعلم إدغام الميم الساكنة في الميم المتحركة.","الإدغام الشفوي هو إدخال الميم الساكنة في الميم التي بعدها لتصبحا ميمًا مشددة.","يكون إذا جاءت ميم متحركة بعد ميم ساكنة، مع غنة ظاهرة منضبطة.",listOf("لَهُمْ مَا يَشَاءُونَ؛ كَمْ مِنْ فِئَةٍ."),"اقرأ المثال مع ملاحظة تشديد الميم الناتجة وغنتها، دون تكرار إغلاق الشفتين مرتين.","إظهار الميمين منفصلتين أو إسقاط التشديد والغنة.","تحفة الأطفال، باب أحكام الميم الساكنة."),
  TajweedLesson(19,"الإظهار الشفوي","أن يميز المتعلم إظهار الميم الساكنة عند غير الباء والميم.","الإظهار الشفوي هو نطق الميم الساكنة واضحة عند حروف الهجاء عدا الباء والميم.","تظهر الميم عند بقية الحروف، ويجب الانتباه خاصة عند الواو والفاء لقرب المخرج.",listOf("أَنْعَمْتَ عَلَيْهِمْ؛ هُمْ فِيهَا؛ أَمْ لَمْ."),"اقرأ أمثلة تتلو فيها الميم الساكنة فاءً أو واوًا أو غيرهما، وأظهر الميم من غير مبالغة.","إخفاء الميم عند الفاء أو الواو أو إدغامها فيما بعدها.","تحفة الأطفال وشروحها، باب أحكام الميم الساكنة."),
  TajweedLesson(20,"النون والميم المشددتان","أن يضبط المتعلم الغنة في النون والميم المشددتين.","الغنة صوت يخرج من الخيشوم، وتلازم النون والميم، وتظهر بوضوح في المشددتين.","يجب إظهار الغنة في النون والميم المشددتين بمقدار حركتين في رواية حفص من طريق الشاطبية، مع تلقي الأداء.",listOf("إِنَّ؛ ثُمَّ؛ عَمَّ؛ النَّاس."),"اقرأ الكلمات منفردة ثم في سياقها، وحافظ على غنة متزنة دون ضغط أو مبالغة.","إضعاف الغنة أو تطويلها أكثر من اللازم أو تحويلها إلى صوت أنفي متكلف.","تحفة الأطفال، باب أحكام الميم والنون المشددتين؛ المقدمة الجزرية.")

  ,TajweedLesson(21,"القلقلة: تعريفها وحروفها","أن يتعرف المتعلم القلقلة وحروفها الخمسة.","القلقلة اضطراب صوت الحرف الساكن عند النطق به حتى يسمع له نبرة واضحة من غير أن يتحول إلى حركة.","حروف القلقلة مجموعة في: قطب جد؛ وتظهر القلقلة عند سكون أحدها، وتختلف قوتها بحسب الموضع والوقف.",listOf("يَقْطَعُونَ؛ أَحَدْ؛ الْفَلَقِ."),"انطق الحروف الخمسة ساكنة في أمثلة صحيحة، وراقب وضوح صوت الحرف دون إضافة فتحة أو ضمة.","تحويل القلقلة إلى حركة كاملة أو المبالغة في إخراج صوت زائد.","المقدمة الجزرية، باب صفات الحروف؛ شروح التجويد في القلقلة."),
  TajweedLesson(22,"مراتب القلقلة","أن يميز المتعلم تفاوت القلقلة بحسب موضع الحرف.","تتفاوت القلقلة في القوة بحسب كون الحرف ساكنًا في وسط الكلمة أو في آخرها عند الوقف، ويذكر أهل الأداء مراتبها بتفصيل.","تراعى القلقلة في الحرف الساكن من غير تكلف، وتكون أوضح عند الوقف على حرف قلقلة مشدد مثل الحقّ.",listOf("يَجْعَلُونَ؛ الْفَلَقْ؛ الْحَقّْ عند الوقف."),"قارن بين قلقلة حرف ساكن وسط الكلمة والوقف على حرف قلقلة، واعرض الأداء على معلم.","اعتبار مراتب القلقلة حركات مستقلة أو إضافة صوت مبالغ فيه بعد الحرف.","شروح المقدمة الجزرية، باب القلقلة؛ كتب الأداء."),
  TajweedLesson(23,"صفات الحروف: اللزوم والعرض","أن يفهم المتعلم الفرق بين الصفات اللازمة والعارضة.","الصفة كيفية تعرض للحرف عند النطق به وتميزه عن غيره؛ فمنها صفات لازمة للحرف، ومنها أحكام عارضة بسبب التركيب.","يتعلم القارئ الصفات اللازمة أولًا، ثم يدرس الأحكام العارضة مثل التفخيم والترقيق والإدغام والإخفاء.",listOf("الجهر والهمس من الصفات اللازمة؛ والإدغام حكم عارض بحسب السياق."),"اختر حرفًا واحدًا وتعرف على صفاته من مرجع تجويد، ثم استمع إلى أدائه في كلمات مختلفة.","الخلط بين مخرج الحرف وصفته، أو تصور أن كل حكم عارض صفة ذاتية للحرف.","المقدمة الجزرية، باب صفات الحروف."),
  TajweedLesson(24,"الهمس والجهر","أن يفرق المتعلم بين الهمس والجهر.","الهمس جريان النفس عند النطق بالحرف، والجهر انحباس جريان النفس.","حروف الهمس مجموعة في فحثه شخص سكت؛ وما عداها من حروف الهجاء حروف جهر على التقسيم المشهور.",listOf("فَ؛ حَ؛ ثَ؛ شَ؛ خَ؛ سَ؛ كَ؛ تَ."),"انطق حرفًا من حروف الهمس ثم حرفًا مجهورًا، ولا تحوّل الهمس إلى همس زائد يضعف الحرف.","إضعاف الحرف المهموس حتى يختفي، أو إخراج نفس زائد مع الحروف المجهورة.","المقدمة الجزرية، باب صفات الحروف؛ كتب التجويد."),
  TajweedLesson(25,"الشدة والرخاوة والتوسط","أن يصنف المتعلم الحروف بحسب جريان الصوت.","الشدة انحباس جريان الصوت، والرخاوة جريانه، والتوسط صفة بينهما.","حروف الشدة مجموعة في أجد قط بكت؛ وحروف التوسط لن عمر؛ وبقية الحروف رخوة بحسب التقسيم المعروف.",listOf("أَجْدُ؛ قَطْ؛ بَكْت؛ لِنْ عُمَر."),"قارن جريان الصوت عند نطق حرف شديد وآخر رخو، واستمع إلى الفرق في الأداء.","إطالة الصوت في الحرف الشديد أو قطع الصوت في الحرف الرخو.","المقدمة الجزرية، باب صفات الحروف."),
  TajweedLesson(26,"الاستعلاء والاستفال","أن يعرف المتعلم حروف الاستعلاء وأثرها في التفخيم.","الاستعلاء ارتفاع أقصى اللسان عند النطق بالحرف، والاستفال عدم ذلك.","حروف الاستعلاء سبعة مجموعة في خص ضغط قظ، وهي مفخمة في الأصل، أما بقية الحروف فمستفلة.",listOf("خَصَّ؛ ضَغْطٍ؛ قِظْ؛ قَالَ؛ كِتَاب."),"اقرأ أمثلة فيها حروف استعلاء مضمومة ومكسورة ومفتوحة، ولا تخلط بين التفخيم والمبالغة.","تفخيم الحروف المستفلة أو ترقيق حروف الاستعلاء بما يغير صفاتها.","المقدمة الجزرية، باب صفات الحروف؛ أبواب التفخيم والترقيق."),
  TajweedLesson(27,"الإطباق والانفتاح","أن يميز المتعلم حروف الإطباق عن غيرها.","الإطباق التصاق جزء من اللسان بما يحاذيه من الحنك الأعلى عند النطق بالحرف، والانفتاح عدم ذلك.","حروف الإطباق أربعة: ص ض ط ظ؛ وهي أقوى تفخيمًا من بقية حروف الاستعلاء لاجتماع الاستعلاء والإطباق فيها.",listOf("صَبْر؛ ضَالِّين؛ طَابَ؛ ظَلَمَ."),"قارن نطق الصاد والسين، والطاء والتاء، والظاء والذال، مع سماع نموذج متقن.","إزالة الإطباق حتى يقترب الحرف من نظيره المنفتح أو المبالغة في الضغط.","المقدمة الجزرية، باب صفات الحروف."),
  TajweedLesson(28,"تفخيم لام لفظ الجلالة وترقيقها","أن يطبق المتعلم حكم اللام في لفظ الجلالة.","لام لفظ الجلالة تفخم إذا سبقها فتح أو ضم، وترقق إذا سبقها كسر.","ينظر إلى حركة الحرف السابق للفظ الجلالة في الوصل: الفتح والضم للتفخيم، والكسر للترقيق.",listOf("قَالَ اللَّهُ؛ عَبْدُ اللَّهِ؛ بِاللَّهِ."),"اقرأ الأمثلة الثلاثة، وحدد حركة ما قبل لفظ الجلالة، ثم طبق التفخيم أو الترقيق.","تفخيم اللام بعد الكسر أو ترقيقها بعد الفتح والضم.","كتب التجويد، باب لام لفظ الجلالة؛ المقدمة الجزرية وشروحها."),
  TajweedLesson(29,"أحوال الراء: التفخيم والترقيق","أن يتعرف المتعلم أشهر ضوابط الراء في رواية حفص.","الراء قد تفخم وقد ترقق بحسب حركتها وحركة ما قبلها والسياق الصوتي.","الأصل أن الراء المفتوحة أو المضمومة مفخمة، والمكسورة مرققة، وللساكنة أحوال تفصيلية واستثناءات لا تضبط إلا بدراسة الباب كاملًا.",listOf("رَبِّ؛ رِزْقًا؛ قُرْآنًا."),"صنف الراء المتحركة في أمثلة واضحة، ثم ادرس الراء الساكنة مع معلم وفق رواية حفص.","تعميم قاعدة واحدة على جميع الراءات الساكنة دون النظر إلى ما قبلها وما بعدها.","كتب التجويد، باب أحكام الراء في رواية حفص."),
  TajweedLesson(30,"المد: تعريفه وأقسامه العامة","أن يفرق المتعلم بين المد الأصلي والفرعي.","المد إطالة الصوت بحرف من حروف المد أو اللين عند وجود سببه، وينقسم إجمالًا إلى أصلي وفرعي.","المد الأصلي لا يتوقف على همز أو سكون، والفرعي سببه همز أو سكون، ومقادير الأداء تضبط بحسب الرواية والطريق.",listOf("قَالَ؛ جَاءَ؛ فِي أَنْفُسِكُمْ."),"حدد حرف المد في أمثلة مختلفة، ثم ابحث هل بعده همز أو سكون لتعرف نوع المد.","تطبيق مقدار واحد على جميع المدود أو مد الحرف من غير تحقق شروطه.","المقدمة الجزرية، باب المد والقصر؛ تحفة الأطفال وشروحها.")
)
